<script setup>
import useModelConfig from '../useModelConfig'
import { getAllModels } from '@/services/models'

const props = defineProps({
  modelId: {
    type: [Number, String],
    default: ''
  },
  model: {
    type: Object,
    default: () => ({})
  }
})

const modelList = ref([])

// 获取并筛选 aliyun 模型，加上“（嵌入）”标识
async function getModelList() {
  await getAllModels().then((res) => {
    const result = res.resData
    modelList.value = result
      .filter((item) => item.provider === 'deepseek_local')
      .map((item) => ({
        ...item,
        displayName: item.type === 'embedding' ? `${item.name}（嵌入）` : item.name
      }))
  })
}

const { apiKey, url, save, loading } = useModelConfig(props)
onMounted(() => {
  getModelList()
})
</script>

<template>
  <div class="flex flex-col items-start justify-start gap-4 p-4 p-4 bg-surface-50 dark:bg-surface-900">
    <div class="w-full">
      <div class="mb-2">API URL</div>
      <InputText
        variant="filled"
        :pt="{ input: { style: { width: '100%' } } }"
        class="password w-full"
        v-model="url"
        toggleMask
        placeholder="http://xxx.com/xxx"
      />
    </div>

    <div class="w-full">
      <div class="mb-2">
        <span>API Key</span>
        <!-- <a
          target="_blank"
          class="py-0.5 text-sm font-medium text-violet-500 underline decoration-zinc-500/20 underline-offset-4 hover:opacity-90"
          href="https://platform.openai.com/api-keys"
        >
          点击获取
        </a> -->
      </div>
      <Password
        variant="filled"
        :pt="{ input: { style: { width: '100%' } } }"
        class="password w-full"
        v-model="apiKey"
        :feedback="false"
        toggleMask
        placeholder="xxxxxxxxxxxxxxxxxxx"
      />
    </div>
    <div class="w-full">
      <span class="text-sm font-semibold text-gray-600 mb-1 block">可用模型列表：</span>
      <ul class="list-disc list-inside text-sm text-gray-800 space-y-1">
        <li v-for="model in modelList" :key="model.id">{{ model.displayName }}</li>
      </ul>
    </div>
    <Button severity="contrast" label="保存" @click="save" :loading="loading"></Button>
  </div>
</template>

<style scoped lang="scss">
.password {
  :deep(.p-password-input) {
    width: 100%;
  }
}
</style>
