import { saveModelKeyUrl } from '../../services/models'
import useModelStore from '../../stores/models'
import useToastService from '@/hooks/useToastService'

const ModelStore = useModelStore()

export default (props) => {
  const apiKey = ref(props.model.api_key)
  const url = ref(props.model.url)
  const dialogRef = inject('dialogRef')

  const loading = ref(false)

  const toast = useToastService()

  function save() {
    const data = {
      id: props.modelId,
      api_key: apiKey.value,
      url: url.value
    }
    loading.value = true
    return saveModelKeyUrl(data)
      .then(() => {
        ModelStore.getModelList()
        toast.add({ severity: 'success', summary: '成功', detail: '保存成功', life: 2000 })
        if (dialogRef.value) {
          dialogRef.value.close()
        }
      })
      .finally(() => {
        loading.value = false
      })
  }

  return { apiKey, url, save, loading }
}
