<script setup>
import useModelConfig from '../useModelConfig'
import Markdown from '@/views/chat/components/Markdown.vue'

const props = defineProps({
  modelId: {
    type: [Number, String],
    default: ''
  },
  model: {
    type: Object,
    default: () => ({})
  }
})

const { url, save, loading } = useModelConfig(props)

const windowsOllamaConfig = `
  #### 步骤 1：在本地安装并启动 Ollama

  确保您的计算机上已安装 Ollama。如果尚未安装，请访问[官方网站](https://ollama.com/download) 进行下载和安装。

  #### 步骤 2：配置 Ollama 的跨域访问

  由于浏览器安全限制，您需要配置 Ollama 的跨域访问权限，以确保其正常运行。

  1. 在 Windows 上，打开**控制面板**，并编辑系统环境变量。
  2. 创建一个新的环境变量，命名为\`OLLAMA_ORIGINS\`（适用于当前用户）。
  3. 将该变量的值设置为\`*\`，然后点击 **OK/Apply**以保存更改。

  #### 步骤 3：拉取模型

  在终端中运行以下命令下载 deepseek 模型：
\`\`\`bash
ollama pull deepseek-r1:1.5b
\`\`\`

  在终端中运行以下命令下载最新的 Qwen3 模型：
\`\`\`bash
ollama pull qwen3:4b
\`\`\`  

模型下载完成后，您可以在聊天中使用它。


  重要提示：完成上述步骤后，请重启 Ollama 服务，以使更改生效。
  `

const emits = defineEmits(['update'])
const inputValue = ref('')
const handleInputChange = (value) => {
  inputValue.value = value.target.value
  emits('update', inputValue.value)
}
</script>

<template>
  <div class="flex flex-col items-start justify-start gap-4 p-4 p-4 bg-surface-50 dark:bg-surface-900">
    <!-- 原有内容保持不变 -->
    <div class="">
      <span>Ollama本地URL</span>
    </div>
    <InputText
      variant="filled"
      :pt="{ input: { style: { width: '100%' } } }"
      class="w-full"
      v-model="url"
      placeholder="http://xxx.com/xxx"
      @input="handleInputChange"
    />
    <Button severity="contrast" label="保存" @click="save" :loading="loading"></Button>
    <Markdown :content="windowsOllamaConfig"></Markdown>
  </div>
</template>

<style scoped lang="scss">
.password {
  :deep(.p-password-input) {
    width: 100%;
  }
}
</style>
